"material": {
  "meta": {
    "title": "Materialfördelar PP-R & PPRCT | K Aqua",
    "desc": "Lär dig varför PP-R och PPRCT från K Aqua är de överlägsna materialen för dricksvatten och industri jämfört med koppar, stål och PVC."
  },
  "hero": {
    "eyebrow": "Polypropen Random Copolymer",
    "title1": "Överlägsenhet genom",
    "title2": "Materialvetenskap.",
    "desc": "Varför PP-R och PPRCT ersätter koppar och stål i den globala rörledningsindustrin. Lär dig de fysikaliska och kemiska fördelarna som gör våra rörsystem till det säkraste valet för dricksvatten och infrastruktur.",
    "cta1": "Jämför med koppar",
    "cta2": "Tekniska Data"
  },
  "section1": {
    "eyebrow": "Problemet med traditionella rör",
    "title": "Korrosion är en tidsinställd bomb.",
    "lead": "Metaller rostar. Det är en fysikalisk lag. Med PP-R eliminerar vi denna felkälla helt och hållet från ekvationen."
  },
  "section2": {
    "eyebrow": "Den molekylära fördelen",
    "title": "Polyfusion: När två blir en.",
    "lead": "Medan andra system förlitar sig på gummitätningar eller gängor, svetsas våra rör ihop på molekylär nivå. Ingen tätning, inget läckage."
  },
  "bento": {
    "items": [
      {
        "title": "100% Korrosionsfri",
        "desc": "Till skillnad från stål- eller kopparrör reagerar PP-R inte kemiskt med vatten eller aggressiva jordar. Inget rostande, ingen gropfrätning (pitting). Röret förblir i sitt ursprungliga skick inuti, decennium efter decennium."
      },
      {
        "title": "Oöverträffad Hygien (Livsmedelssäker)",
        "desc": "PP-R är kemiskt inert och helt fritt från tungmetaller som bly eller nickel. Den extremt släta innerytan (grovhet 0,007 mm) förhindrar kalkavlagringar och berövar bakterier (som legionella) deras grogrund. Ditt dricksvatten förblir rent."
      },
      {
        "title": "Långsiktig Hållbarhet",
        "desc": "Designad för en livslängd på över 50 år vid kontinuerlig drift, även under svåra tryck- och temperaturförhållanden. En investering i generationer."
      },
      {
        "title": "Hög Kemisk Beständighet",
        "desc": "Extremt motståndskraftigt mot hundratals industrikemikalier, klorerade vätskor och syror. Idealisk för laboratorier, processkylning och simbassänger."
      }
    ]
  },
  "timeline": {
    "title": "Teknisk Evolution",
    "desc": "Från standard PP-R till högkristallint PPRCT: Hur K Aqua kontinuerligt tänjer på gränserna för polymervetenskapen.",
    "items": [
      {
        "year": "Material",
        "title": "PP-R (Typ 3)",
        "text": "Polypropen Random Copolymer är branschstandarden. Genom en speciell molekylär struktur av propen- och etylkedjor uppnår materialet en exceptionell slaghållfasthet och elasticitet, perfekt för standardtillämpningar."
      },
      {
        "year": "Evolution",
        "title": "PPRCT (Typ 4)",
        "text": "Den fjärde generationen (Polypropylene Random Copolymer with Modified Crystallinity). Genom förbättrad kristallin struktur erbjuder det betydligt högre tryckhållfasthet vid höga temperaturer (upp till 95°C)."
      },
      {
        "year": "Fördelen",
        "title": "Högre hydraulisk kapacitet",
        "text": "Tack vare PPRCT:s styrka kan rörets väggtjocklek minskas (vid samma tryckklass). Detta leder till upp till 17% högre vattenflöde och enklare hantering på byggarbetsplatsen tack vare lägre vikt."
      },
      {
        "year": "Innovation",
        "title": "K-Fiber (Faserkomposit)",
        "text": "Ett treskiktsrör med en central glasfiberförstärkt PP-R-kärna. Denna teknik minskar den termiska längdutvidgningen med 75%, vilket drastiskt minskar antalet rörklamrar och expansionskompensatorer som krävs."
      },
      {
        "year": "Framtiden",
        "title": "UV- & Antimikrobiell",
        "text": "Framtidsorienterade co-extruderingsprocesser möjliggör rör med UV-resistenta ytterskikt för obegränsad utomhusinstallation, samt antibakteriella inre kärnor för sjukhusmiljöer."
      }
    ]
  },
  "stats": {
    "eyebrow": "PP-R vs Metall",
    "title": "Ingenjörskonst i Siffror.",
    "items": [
      {
        "label": "Grovhet (K-värde)",
        "value": "0,007 mm",
        "sub": "Koppar: 0,015 mm / Stål: 0,15 mm"
      },
      {
        "label": "Termisk ledningsförmåga",
        "value": "0,24 W/mK",
        "sub": "Isolerar naturligt, mindre värmeförlust"
      },
      {
        "label": "Ljudisolering",
        "value": "-10 dB",
        "sub": "Absorberar flödesljud extremt bra"
      },
      {
        "label": "Densitet",
        "value": "0,9 g/cm³",
        "sub": "9 gånger lättare än stål"
      }
    ]
  },
  "cta": {
    "eyebrow": "RÅDGIVNING",
    "title1": "LÅT OSS PRATA",
    "title2": "MATERIAL.",
    "desc": "Är du osäker på om PP-R eller PPRCT är rätt för ditt projekt? Våra materialexperter jämför krav och levererar belastbara beräkningar.",
    "button1": "Boka Expertrådgivning",
    "button2": "Ladda ner Materialblad"
  }
