"krankenhaus": {
  "meta": {
    "title": "Sjukhus rörsystem | K Aqua",
    "desc": "K Aqua rörsystem för sjukhus: Maximal hygien, noll korrosion. Lär dig hur vår tyska teknik skyddar patienter."
  },
  "hero": {
    "eyebrow": "Kritisk infrastruktur",
    "title1": "Där varje detalj",
    "title2": "kan rädda liv.",
    "desc": "På sjukhus och kliniker kompromissar man inte med vattenkvaliteten. K Aqua erbjuder det säkraste, mest hygieniska och korrosionsfria PP-R rörsystemet på den globala marknaden.",
    "cta1": "Få rådgivning",
    "cta2": "Tekniska data"
  },
  "intro": {
    "title": "Hygien är inte förhandlingsbart.",
    "desc": "Vårdinrättningar har de strängaste kraven på dricksvatteninfrastruktur i världen. Legionella, pseudomonas och andra patogener utgör dödliga hot. Konventionella rör av koppar eller stål bildar med tiden mikroskopiska porer och avlagringar – den perfekta grobädden för biofilmsbildning.\nK Aquas PP-R (Polypropen Random Copolymer) sätter nya standarder här. Den extremt släta, kemiskt inerta ytan erbjuder ingen fästpunkt för mikroorganismer och reagerar inte kemiskt med vattnet. Resultatet är absolut renhet, årtionde efter årtionde."
  },
  "stickySection": {
    "eyebrow": "Systemkrav"
  },
  "sticky": {
    "items": [
      {
        "title": "Inkrustation & Biofilm",
        "desc": "K Aquas extremt släta inneryta (råhet 0,007 mm) förhindrar kalkavlagringar och därmed bildandet av biofilm, där patogener vanligtvis förökar sig."
      },
      {
        "title": "Kemisk resistens",
        "desc": "Systemet tål desinfektionsmedel och uppfyller de högsta hygienkraven i känsliga områden (t.ex. operationssalar, intensivvård)."
      },
      {
        "title": "Termisk isolering",
        "desc": "Materialets låga värmeledningsförmåga bibehåller rätt temperatur. Varmvattnet förblir varmt, kallvattnet kallt. En av de mest kritiska faktorerna för legionellaprevention."
      },
      {
        "title": "Akustisk dämpning",
        "desc": "Materialets utmärkta ljudabsorberande egenskaper säkerställer tyst flöde och noll vattenslag, avgörande för patientens komfort."
      }
    ]
  },
  "timelineSection": {
    "title": "Vägen till rent vatten."
  },
  "timeline": {
    "items": [
      {
        "year": "Mål",
        "title": "Absolut hygien",
        "text": "Systemet måste stödja nolltoleranspolicyn mot nosokomiala infektioner och säkerställa en oklanderlig dricksvattenkvalitet (VDI 6023)."
      },
      {
        "year": "Krav",
        "title": "Långsiktig säkerhet",
        "text": "Långsiktigt motstånd mot desinfektion och termiska chocker, som ingår i hygienplanen."
      },
      {
        "year": "Design",
        "title": "Cirkulation",
        "text": "Konsekvent utformning som cirkulerande system för att utesluta stagnation."
      },
      {
        "year": "Utförande",
        "title": "Homogen svetsning",
        "text": "Polyfusion resulterar i ett system utan döda utrymmen och utan risker från O-ringar och tätningar."
      },
      {
        "year": "Drift",
        "title": "Pålitlighet",
        "text": "Decennier av prestanda med konstant låga driftkostnader och minimalt underhåll."
      }
