"hotels": {
  "meta": {
    "title": "Rörsystem för hotell och resorter | K Aqua",
    "desc": "K Aqua: Osynlig lyx för topphotell. Tyst, hygienisk och oförstörbar vatteninfrastruktur för lyxresorter över hela världen."
